        items: [
          '**256K is mainstream, 1M is possible.** Qwen3.5, Qwen3.8 and Gemma 4 (12B, 26B, 31B) list 256K windows in the Ollama library. Nemotron 3 Nano 30B supports 1M. Gemma 4 E2B/E4B, Mistral Small 3.2, gpt-oss 20B and Llama 3.1 8B stay at 128K.',
          '**The KV cache decides memory, and it depends on the architecture.** At 128K the f16 cache takes 16 GiB for Llama 3.1 8B, 8 GiB for Qwen3.8 27B, about 2.7 GiB for Gemma 4 26B-A4B and about 0.75 GiB for Nemotron 3 Nano.',
          '**Hybrid architectures make long windows cheap.** Sliding-window attention (Gemma 4, gpt-oss), Gated DeltaNet (Qwen3.5, Qwen3.8) and Mamba-2 (Nemotron 3 Nano) replace many full-attention layers, and only full-attention layers grow with the window.',
          '**Ollama defaults to 4K tokens below 24 GiB of VRAM**, 32K from 24 to 48 GiB and 256K from 48 GiB. Set the context explicitly and check it with ollama ps.',
          '**Usable context is shorter than advertised.** RULER and NoLiMa found large accuracy drops at 32K for many models that claim 128K or more. Put critical facts at the start or end and test at your target length.',
          '**Choose by task.** RAG suits search across many documents. Long context suits reasoning across one coherent document, such as a contract, a codebase or a book.',
        ],
