      whatIsContext: {
        id: 'what-is-context-length',
        title: 'What Is Context Length and Why Does It Matter for Local LLMs?',
        content: [
          '**Context length is the maximum number of tokens a model can hold in one request: your prompt, any documents, the conversation so far and the answer it writes, added together.** One token is about 0.75 English words, so 128K tokens is about 100,000 words and 256K tokens about 200,000 words.',
          'The advertised window is the maximum the model architecture supports. The usable window is the length at which answers stay accurate for your task, and it is shorter.',
          'Long windows matter for whole codebases, contracts, long transcripts, book chapters and agent sessions where tool output piles up. The Ollama documentation recommends at least 64,000 tokens for agents, web search and coding tools.',
          'Three things set the limit on your own machine: the model\'s window, the memory its KV cache needs at that length and how reliably it uses text at that length. The next sections cover each in turn.',
        ],
      },
