      faqSection: {
        id: 'faq',
        title: 'Frequently Asked Questions',
        faqs: [
          {
            q: 'What is the longest context window a local LLM can use in 2026?',
            a: 'Llama 4 Scout lists 10M tokens, but its model card reports benchmarks at 128K and the Ollama download is 67 GB. Among models that run on one consumer machine, NVIDIA Nemotron 3 Nano 30B-A3B supports 1M tokens (256K is the default configuration), and Qwen3.8 and Qwen3.5 support 256K natively with up to roughly 1M through YaRN. Whether a long window is usable depends on memory and on how accurately the model reads long inputs.',
          },
          {
            q: 'Is a 128K context window still enough?',
            a: '128K tokens is about 100,000 words, enough for most single documents. A 300-page book is typically 75,000 to 100,000 words, roughly 100K to 135K tokens, so it usually exceeds or barely fits a 128K window with no room for questions and answers. A 256K window holds the book and the answer; beyond that, use RAG or chunking.',
          },
          {
            q: 'How much memory does a 1M-token context need?',
            a: 'It depends on the architecture. By the published configurations, the f16 KV cache at 1M tokens is about 32 GiB for Qwen3.5 9B, about 64 GiB for Qwen3.8 27B and about 6 GiB for Nemotron 3 Nano 30B-A3B, on top of the weights. Qwen states that 1M tokens on Qwen3-30B-A3B-Instruct-2507 needs about 240 GB of GPU memory. A q8_0 cache halves the KV figures, and the time to read a 1M-token prompt grows with its length, so reserve it for occasional jobs.',
          },
          {
            q: 'Why do models with the same context window need different amounts of memory?',
            a: 'The KV cache grows with full-attention layers × KV heads × head dimension × tokens. Llama 3.1 8B needs 128 KiB per token, Gemma 4 26B-A4B about 20 KiB because only 5 of its 30 layers use full attention, and Nemotron 3 Nano about 6 KiB because only 6 of its 52 layers are attention layers. Sliding-window, linear-attention and Mamba layers keep a fixed-size state instead of growing with the window.',
          },
          {
            q: 'What is the KV cache and how can I make it smaller?',
            a: 'The KV cache holds the attention keys and values of every token in the context so the model does not recompute them for each new token. It is allocated on top of the weights and grows with context length. To shrink it, lower num_ctx, enable Flash Attention and set OLLAMA_KV_CACHE_TYPE to q8_0 (about half the memory of f16) or q4_0 (about a quarter, with more precision loss at long contexts), or choose a model with a smaller cache per token. In Ollama the cache type is global and applies to every model.',
          },
          {
            q: 'Why does my local model forget the start of my document?',
            a: 'Most likely the active context is smaller than your document. Ollama defaults to 4K tokens on GPUs with under 24 GiB of VRAM, 32K from 24 to 48 GiB and 256K from 48 GiB, whatever the model supports, and input beyond the context is truncated. Check the CONTEXT column of ollama ps and raise it with OLLAMA_CONTEXT_LENGTH, /set parameter num_ctx, a Modelfile or the API num_ctx option.',
          },
          {
            q: 'How do I set a 128K context in Ollama?',
            a: 'Create a Modelfile with FROM qwen3.5:9b and PARAMETER num_ctx 131072, run ollama create qwen3.5-9b-128k -f Modelfile, then ollama run qwen3.5-9b-128k and verify with ollama ps. Alternatively start the server with OLLAMA_CONTEXT_LENGTH=131072 ollama serve. Make sure weights plus KV cache fit in memory first; for Qwen3.5 9B that is about 6.6 GB plus 4 GiB.',
          },
          {
            q: 'Does a longer context make a local LLM slower?',
            a: 'Yes. The model must read the whole prompt (prefill) before it writes the first token, so time to first token grows with prompt length, and attention over a larger cache also lowers generation speed. Linear-attention and Mamba layers reduce the growth but do not remove it. Measure on your hardware with ollama run <model> --verbose, which prints prompt-evaluation and generation rates.',
          },
          {
            q: 'What is the "lost in the middle" problem and does it still apply?',
            a: 'Liu et al. (2023) found that language models answer most accurately when the relevant text is at the start or the end of the input and less accurately when it is in the middle. RULER (2024) and NoLiMa (2025) later showed that many models claiming 32K to 128K windows lose accuracy well before their limit. Those studies tested earlier models, so run your own check: hide a fact at 10%, 50% and 90% of a long prompt and ask about it. Put critical instructions at the start or end, or retrieve only the relevant passages.',
          },
          {
            q: 'Is long context or RAG better for document question answering?',
            a: 'RAG is usually cheaper in memory and time when the answer sits in a few passages of a large collection, because it keeps the prompt to a few thousand tokens. Long context is better when the model must reason across one coherent document, such as a contract, a codebase or a book chapter, where chunking would split cross-references. Many setups combine both by retrieving whole sections into a 32K to 128K window.',
          },
          {
            q: 'Can I summarize an entire book with a local LLM?',
            a: 'A 300-page book is roughly 100K to 135K tokens, so it fits a 256K window (Qwen3.5, Qwen3.8, Gemma 4 12B and larger) and may not fit a 128K window once the summary is counted. With a 128K model or less memory, summarize chapter by chapter and then summarize the summaries. Set num_ctx explicitly so the whole book is in the active context.',
          },
          {
            q: 'Do non-English documents use more of the context window?',
            a: 'They can. Petrov et al. (2023) found that the same text can need up to 15 times more tokens in one language than in another, depending on the tokenizer. Count tokens with your model instead of using the English rule of 0.75 words per token: ollama run <model> --verbose prints the prompt token count.',
          },
          {
            q: 'Which long-context models run on a 16 GB machine?',
            a: 'By memory arithmetic, Qwen3.5 9B (6.6 GB download plus about 4 GiB of KV cache at 128K) and Gemma 4 12B (7.7 GB plus about 4.3 GiB at its full 256K window) fit in 16 GB with a few GB to spare. These are calculations from published configurations, not measured runs; confirm with ollama ps.',
          },
        ],
      },
