    title: 'LLM locales con contexto largo 2026: modelos de 128K, 256K y 1M comparados',
    seoTitle: 'LLM locales con contexto largo (2026): de 128K a 1M',
    intro: 'En 2026, 128K tokens es el nivel de entrada de los LLM locales, no el techo. La biblioteca de Ollama lista ventanas de 256K para Qwen3.5, Qwen3.8 y Gemma 4 (desde 12B), 1M para NVIDIA Nemotron 3 Nano 30B y 10M para Llama 4 Scout. La memoria es el límite real: la caché KV a 128K ocupa desde menos de 1 GiB (Nemotron 3 Nano) hasta 20 GiB (Mistral Small 3.2) según la arquitectura, y Ollama usa por defecto solo 4K tokens en GPU con menos de 24 GiB de VRAM. Esta guía indica qué modelos admiten cada ventana, cuánta memoria cuesta cada una y cómo ajustar la longitud de contexto.',
    metaDescription: 'Los LLM locales ya llegan a 256K tokens (Qwen3.8, Gemma 4) y 1M (Nemotron 3 Nano). Memoria de la caché KV por modelo y cómo ajustar el contexto en Ollama.',
