          'La tabla muestra la ventana que indican la ficha del modelo o la biblioteca de Ollama. Una extensión de contexto, como YaRN, es una opción documentada por el fabricante que requiere configuración y memoria adicionales.',
          'Llama 4 Scout lista 10M tokens, pero su ficha publica los benchmarks de contexto largo con una ventana de 128K, y la descarga de Ollama es de 67 GB. Llama 4 Maverick lista 1M, pero su descarga es de 245 GB, así que requiere hardware de servidor.',
