      faqSection: {
        id: 'faq',
        title: 'Preguntas frecuentes',
        faqs: [
          {
            q: '¿Cuál es la ventana de contexto más larga que puede usar un LLM local en 2026?',
            a: 'Llama 4 Scout lista 10M tokens, pero su ficha publica benchmarks a 128K y la descarga de Ollama es de 67 GB. Entre los modelos que funcionan en un equipo de consumo, NVIDIA Nemotron 3 Nano 30B-A3B admite 1M tokens (256K es la configuración por defecto), y Qwen3.8 y Qwen3.5 admiten 256K de forma nativa y hasta aproximadamente 1M con YaRN. Que una ventana larga sea utilizable depende de la memoria y de la precisión con la que el modelo lee entradas largas.',
          },
          {
            q: '¿Sigue siendo suficiente una ventana de contexto de 128K?',
            a: '128K tokens son unas 100,000 palabras, suficientes para la mayoría de los documentos individuales. Un libro de 300 páginas suele tener entre 75,000 y 100,000 palabras, unos 100K a 135K tokens, así que normalmente supera una ventana de 128K o apenas cabe, sin espacio para preguntas y respuestas. Una ventana de 256K contiene el libro y la respuesta; más allá, usa RAG o fragmentación.',
          },
          {
            q: '¿Cuánta memoria necesita un contexto de 1M tokens?',
            a: 'Depende de la arquitectura. Según las configuraciones publicadas, la caché KV en f16 a 1M tokens es de unos 32 GiB en Qwen3.5 9B, unos 64 GiB en Qwen3.8 27B y unos 6 GiB en Nemotron 3 Nano 30B-A3B, además de los pesos. Qwen indica que 1M tokens con Qwen3-30B-A3B-Instruct-2507 necesitan unos 240 GB de memoria de GPU. Una caché q8_0 reduce a la mitad los valores de KV, y el tiempo de leer un prompt de 1M tokens crece con su longitud, así que resérvalo para tareas ocasionales.',
          },
          {
            q: '¿Por qué modelos con la misma ventana de contexto necesitan cantidades distintas de memoria?',
            a: 'La caché KV crece con capas de atención completa × cabezas KV × dimensión de cabeza × tokens. Llama 3.1 8B necesita 128 KiB por token, Gemma 4 26B-A4B unos 20 KiB porque solo 5 de sus 30 capas usan atención completa, y Nemotron 3 Nano unos 6 KiB porque solo 6 de sus 52 capas son de atención. Las capas de ventana deslizante, de atención lineal y Mamba mantienen un estado de tamaño fijo en lugar de crecer con la ventana.',
          },
          {
            q: '¿Qué es la caché KV y cómo puedo reducirla?',
            a: 'La caché KV guarda las claves y valores de atención de cada token del contexto para que el modelo no los recalcule con cada token nuevo. Se reserva además de los pesos y crece con la longitud de contexto. Para reducirla, baja num_ctx, activa Flash Attention y define OLLAMA_KV_CACHE_TYPE como q8_0 (aproximadamente la mitad de la memoria de f16) o q4_0 (aproximadamente una cuarta parte, con más pérdida de precisión en contextos largos), o elige un modelo con una caché menor por token. En Ollama el tipo de caché es global y se aplica a todos los modelos.',
          },
          {
            q: '¿Por qué mi modelo local olvida el principio de mi documento?',
            a: 'Lo más probable es que el contexto activo sea más pequeño que tu documento. Ollama usa por defecto 4K tokens en GPU con menos de 24 GiB de VRAM, 32K entre 24 y 48 GiB y 256K desde 48 GiB, sea cual sea el soporte del modelo, y la entrada que supera el contexto se trunca. Comprueba la columna CONTEXT de ollama ps y súbelo con OLLAMA_CONTEXT_LENGTH, /set parameter num_ctx, un Modelfile o la opción num_ctx de la API.',
          },
          {
            q: '¿Cómo configuro un contexto de 128K en Ollama?',
            a: 'Crea un Modelfile con FROM qwen3.5:9b y PARAMETER num_ctx 131072, ejecuta ollama create qwen3.5-9b-128k -f Modelfile, luego ollama run qwen3.5-9b-128k y verifica con ollama ps. Como alternativa, inicia el servidor con OLLAMA_CONTEXT_LENGTH=131072 ollama serve. Antes comprueba que los pesos más la caché KV caben en memoria; en Qwen3.5 9B son unos 6.6 GB más 4 GiB.',
          },
          {
            q: '¿Un contexto más largo hace más lento a un LLM local?',
            a: 'Sí. El modelo debe leer todo el prompt (prellenado) antes de escribir el primer token, así que el tiempo hasta el primer token crece con la longitud del prompt, y la atención sobre una caché mayor también reduce la velocidad de generación. Las capas de atención lineal y Mamba reducen el crecimiento, pero no lo eliminan. Mide en tu hardware con ollama run <model> --verbose, que muestra las velocidades de evaluación del prompt y de generación.',
          },
          {
            q: '¿Qué es el problema «lost in the middle» y sigue vigente?',
            a: 'Liu et al. (2023) comprobaron que los modelos de lenguaje responden con más precisión cuando el texto relevante está al principio o al final de la entrada y con menos precisión cuando está en el medio. RULER (2024) y NoLiMa (2025) mostraron después que muchos modelos con ventanas de 32K a 128K pierden precisión mucho antes de su límite. Esos estudios probaron modelos anteriores, así que haz tu propia comprobación: esconde un dato al 10 %, 50 % y 90 % de un prompt largo y pregúntalo. Pon las instrucciones críticas al principio o al final, o recupera solo los pasajes relevantes.',
          },
          {
            q: '¿Es mejor el contexto largo o RAG para responder preguntas sobre documentos?',
            a: 'RAG suele costar menos memoria y tiempo cuando la respuesta está en unos pocos pasajes de una colección grande, porque mantiene el prompt en unos pocos miles de tokens. El contexto largo es mejor cuando el modelo debe razonar sobre un documento coherente, como un contrato, una base de código o un capítulo de libro, donde la fragmentación partiría referencias cruzadas. Muchas configuraciones combinan ambos recuperando secciones completas en una ventana de 32K a 128K.',
          },
          {
            q: '¿Puedo resumir un libro entero con un LLM local?',
            a: 'Un libro de 300 páginas son unos 100K a 135K tokens, así que cabe en una ventana de 256K (Qwen3.5, Qwen3.8, Gemma 4 desde 12B) y puede no caber en una de 128K al contar el resumen. Con un modelo de 128K o menos memoria, resume capítulo por capítulo y después resume los resúmenes. Define num_ctx de forma explícita para que todo el libro esté en el contexto activo.',
          },
          {
            q: '¿Los documentos en otros idiomas consumen más ventana de contexto?',
            a: 'Pueden hacerlo. Petrov et al. (2023) comprobaron que el mismo texto puede necesitar hasta 15 veces más tokens en un idioma que en otro, según el tokenizador. Cuenta los tokens con tu modelo en lugar de usar la regla inglesa de 0.75 palabras por token: ollama run <model> --verbose muestra el número de tokens del prompt.',
          },
          {
            q: '¿Qué modelos de contexto largo funcionan en un equipo de 16 GB?',
            a: 'Por aritmética de memoria, Qwen3.5 9B (descarga de 6.6 GB más unos 4 GiB de caché KV a 128K) y Gemma 4 12B (7.7 GB más unos 4.3 GiB en su ventana completa de 256K) caben en 16 GB con unos GB de margen. Son cálculos a partir de configuraciones publicadas, no ejecuciones medidas; confirma con ollama ps.',
          },
        ],
      },
