          '[NVIDIA. (2025). "NVIDIA-Nemotron-3-Nano-30B-A3B-BF16" model card. huggingface.co](https://huggingface.co/nvidia/NVIDIA-Nemotron-3-Nano-30B-A3B-BF16) -- 23 capas Mamba-2 y MoE más 6 capas de atención, 1M admitido, 256K por defecto.',
          '[Meta. (2025). "Llama-4-Scout-17B-16E-Instruct" model card. huggingface.co](https://huggingface.co/meta-llama/Llama-4-Scout-17B-16E-Instruct) -- 109B en total, 10M listados, benchmarks de contexto largo a 128K.',
          '[Unsloth. (2026). "NVIDIA Nemotron 3 Nano -- How To Run Guide". unsloth.ai](https://unsloth.ai/docs/models/nemotron-3) -- el contexto de 1M puede quedarse sin memoria, 262,144 por defecto.',
