          '[Modarressi et al. (2025). "NoLiMa: Long-Context Evaluation Beyond Literal Matching". arxiv.org](https://arxiv.org/abs/2502.05167) -- 11 de 13 modelos caen por debajo del 50 % de su puntuación con contexto corto a 32K.',
          '[Petrov et al. (2023). "Language Model Tokenizers Introduce Unfairness Between Languages". arxiv.org](https://arxiv.org/abs/2305.15425) -- hasta 15 veces más tokens para el mismo texto.',
