    intro: 'في عام 2026 أصبح سياق 128K رمز مستوى الدخول لنماذج LLM المحلية لا سقفها. تُدرج مكتبة Ollama نوافذ 256K لنماذج Qwen3.5 وQwen3.8 وGemma 4 (من 12B فما فوق)، و1M لنموذج NVIDIA Nemotron 3 Nano 30B، و10M لنموذج Llama 4 Scout. الحد الحقيقي هو الذاكرة: يشغل KV cache عند 128K من أقل من 1 GiB (Nemotron 3 Nano) إلى 20 GiB (Mistral Small 3.2) بحسب البنية، وتستخدم Ollama افتراضياً 4K رمز فقط على وحدات GPU التي تقل VRAM فيها عن 24 GiB. يوضح هذا الدليل أي النماذج تدعم أي نافذة، وكم تكلف كل نافذة من الذاكرة، وكيف تضبط طول السياق.',
