    faqSchema: {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: [
        {
          '@type': 'Question',
          name: 'Qual é a maior janela de contexto que um LLM local pode usar em 2026?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'O Llama 4 Scout lista 10M tokens, mas sua ficha divulga benchmarks a 128K e o download no Ollama tem 67 GB. Entre os modelos que rodam em uma máquina comum, o NVIDIA Nemotron 3 Nano 30B-A3B suporta 1M tokens (256K é a configuração padrão), e o Qwen3.8 e o Qwen3.5 suportam 256K nativamente e até cerca de 1M com YaRN. Se uma janela longa é utilizável depende da memória e da precisão com que o modelo lê entradas longas.',
          },
        },
        {
          '@type': 'Question',
          name: 'Uma janela de contexto de 128K ainda é suficiente?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '128K tokens são cerca de 100.000 palavras, suficientes para a maioria dos documentos isolados. Um livro de 300 páginas costuma ter de 75.000 a 100.000 palavras, algo como 100K a 135K tokens, então normalmente excede uma janela de 128K ou mal cabe, sem espaço para perguntas e respostas. Uma janela de 256K comporta o livro e a resposta; além disso, use RAG ou divisão em partes.',
          },
        },
        {
          '@type': 'Question',
          name: 'Quanta memória um contexto de 1M tokens exige?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Depende da arquitetura. Pelas configurações publicadas, o cache KV em f16 a 1M tokens é de cerca de 32 GiB no Qwen3.5 9B, cerca de 64 GiB no Qwen3.8 27B e cerca de 6 GiB no Nemotron 3 Nano 30B-A3B, além dos pesos. A Qwen informa que 1M tokens no Qwen3-30B-A3B-Instruct-2507 exigem cerca de 240 GB de memória de GPU. Um cache q8_0 reduz os valores de KV pela metade, e o tempo para ler um prompt de 1M tokens cresce com o tamanho dele, então reserve-o para tarefas ocasionais.',
          },
        },
        {
          '@type': 'Question',
          name: 'Por que modelos com a mesma janela de contexto precisam de quantidades diferentes de memória?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'O cache KV cresce com camadas de atenção completa × cabeças KV × dimensão da cabeça × tokens. O Llama 3.1 8B precisa de 128 KiB por token, o Gemma 4 26B-A4B de cerca de 20 KiB porque só 5 das suas 30 camadas usam atenção completa, e o Nemotron 3 Nano de cerca de 6 KiB porque só 6 das suas 52 camadas são de atenção. Camadas de janela deslizante, de atenção linear e Mamba mantêm um estado de tamanho fixo em vez de crescer com a janela.',
          },
        },
        {
          '@type': 'Question',
          name: 'O que é o cache KV e como posso reduzi-lo?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'O cache KV guarda as chaves e os valores de atenção de cada token do contexto para que o modelo não os recalcule a cada novo token. Ele é alocado além dos pesos e cresce com o tamanho do contexto. Para reduzi-lo, diminua num_ctx, ative o Flash Attention e defina OLLAMA_KV_CACHE_TYPE como q8_0 (cerca de metade da memória do f16) ou q4_0 (cerca de um quarto, com mais perda de precisão em contextos longos), ou escolha um modelo com cache menor por token. No Ollama, o tipo de cache é global e vale para todos os modelos.',
          },
        },
        {
          '@type': 'Question',
          name: 'Por que meu modelo local esquece o início do meu documento?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Provavelmente o contexto ativo é menor que o seu documento. O Ollama usa por padrão 4K tokens em GPUs com menos de 24 GiB de VRAM, 32K de 24 a 48 GiB e 256K a partir de 48 GiB, seja qual for o suporte do modelo, e a entrada além do contexto é truncada. Confira a coluna CONTEXT do ollama ps e aumente com OLLAMA_CONTEXT_LENGTH, /set parameter num_ctx, um Modelfile ou a opção num_ctx da API.',
          },
        },
        {
          '@type': 'Question',
          name: 'Como defino um contexto de 128K no Ollama?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Crie um Modelfile com FROM qwen3.5:9b e PARAMETER num_ctx 131072, execute ollama create qwen3.5-9b-128k -f Modelfile, depois ollama run qwen3.5-9b-128k e verifique com ollama ps. Como alternativa, inicie o servidor com OLLAMA_CONTEXT_LENGTH=131072 ollama serve. Antes, confirme que pesos mais cache KV cabem na memória; no Qwen3.5 9B são cerca de 6.6 GB mais 4 GiB.',
          },
        },
        {
          '@type': 'Question',
          name: 'Um contexto mais longo deixa um LLM local mais lento?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Sim. O modelo precisa ler todo o prompt (preenchimento) antes de escrever o primeiro token, então o tempo até o primeiro token cresce com o tamanho do prompt, e a atenção sobre um cache maior também reduz a velocidade de geração. Camadas de atenção linear e Mamba diminuem o crescimento, mas não o eliminam. Meça no seu hardware com ollama run <model> --verbose, que mostra as taxas de avaliação do prompt e de geração.',
          },
        },
        {
          '@type': 'Question',
          name: 'O que é o problema «lost in the middle» e ele ainda vale?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Liu et al. (2023) constataram que modelos de linguagem respondem com mais precisão quando o texto relevante está no início ou no fim da entrada e com menos precisão quando está no meio. RULER (2024) e NoLiMa (2025) mostraram depois que muitos modelos com janelas de 32K a 128K perdem precisão bem antes do limite. Esses estudos testaram modelos anteriores, então faça sua própria verificação: esconda um fato a 10 %, 50 % e 90 % de um prompt longo e pergunte sobre ele. Coloque instruções críticas no início ou no fim, ou recupere só os trechos relevantes.',
          },
        },
        {
          '@type': 'Question',
          name: 'Contexto longo ou RAG é melhor para perguntas e respostas sobre documentos?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'O RAG costuma custar menos memória e tempo quando a resposta está em poucos trechos de uma coleção grande, porque mantém o prompt em poucos milhares de tokens. O contexto longo é melhor quando o modelo precisa raciocinar sobre um documento coerente, como um contrato, uma base de código ou um capítulo de livro, em que a divisão em partes separaria referências cruzadas. Muitas configurações combinam os dois, recuperando seções inteiras em uma janela de 32K a 128K.',
          },
        },
        {
          '@type': 'Question',
          name: 'Posso resumir um livro inteiro com um LLM local?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Um livro de 300 páginas tem cerca de 100K a 135K tokens, então cabe em uma janela de 256K (Qwen3.5, Qwen3.8, Gemma 4 a partir de 12B) e pode não caber em uma de 128K quando o resumo é contado. Com um modelo de 128K ou menos memória, resuma capítulo por capítulo e depois resuma os resumos. Defina num_ctx explicitamente para que o livro inteiro esteja no contexto ativo.',
          },
        },
        {
          '@type': 'Question',
          name: 'Documentos em outros idiomas usam mais da janela de contexto?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Podem usar. Petrov et al. (2023) constataram que o mesmo texto pode exigir até 15 vezes mais tokens em um idioma do que em outro, conforme o tokenizador. Conte os tokens com o seu modelo em vez de usar a regra inglesa de 0.75 palavra por token: ollama run <model> --verbose mostra a contagem de tokens do prompt.',
          },
        },
        {
          '@type': 'Question',
          name: 'Quais modelos de contexto longo rodam em uma máquina de 16 GB?',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Pela aritmética de memória, o Qwen3.5 9B (download de 6.6 GB mais cerca de 4 GiB de cache KV a 128K) e o Gemma 4 12B (7.7 GB mais cerca de 4.3 GiB na janela completa de 256K) cabem em 16 GB com alguns GB de folga. São cálculos a partir de configurações publicadas, não execuções medidas; confirme com ollama ps.',
          },
        },
      ],
      inLanguage: 'pt-BR',
    },
