          'Você pode definir o contexto com o controle deslizante do app do Ollama, a variável de ambiente OLLAMA_CONTEXT_LENGTH, /set parameter num_ctx dentro do ollama run, um Modelfile ou a opção num_ctx da API. Confirme o resultado com ollama ps.',
          'No LM Studio, abra My Models, clique no ícone de engrenagem de um modelo e defina o tamanho do contexto e o Flash Attention. No llama.cpp, -c define o tamanho do contexto (0 o carrega do modelo), -fa controla o Flash Attention e --cache-type-k e --cache-type-v quantizam o cache KV.',
          'O Ollama só quantiza o cache KV quando o Flash Attention está ligado, e o ajuste é global para todos os modelos. OLLAMA_KV_CACHE_TYPE=q8_0 usa cerca de metade da memória do f16 e q4_0 cerca de um quarto.',
