          '**Presumir que toda tag tem a janela longa:** na biblioteca do Ollama, qwen3:14b lista 40K enquanto qwen3:30b lista 256K. Leia o valor de contexto na página do modelo antes de planejar.',
          '**Tratar a janela anunciada como a utilizável:** RULER e NoLiMa encontraram quedas fortes de precisão a 32K em muitos modelos que anunciam 128K ou mais. Teste com seus próprios documentos no tamanho que pretende usar.',
          '**Recorrer a 1M tokens por padrão:** o tempo de preenchimento e a memória crescem com o prompt, e a Unsloth alerta que 1M pode provocar travamentos por falta de memória no Nemotron 3 Nano. Use 1M em tarefas ocasionais e prefira RAG ou divisão em partes no dia a dia.',
