          '**16 GB:** Qwen3.5 9B (6,6 GB) passt mit etwa 4 GiB KV-Cache in 128K. Gemma 4 12B (7,7 GB) passt mit etwa 4,3 GiB in sein volles 256K-Fenster.',
          '**24 bis 32 GB:** Gemma 4 26B-A4B (16 GB) braucht bei 256K etwa 5,2 GiB. Qwen3.8 27B (18 GB) braucht bei 128K etwa 8 GiB. gpt-oss 20B (14 GB) braucht bei seinem 128K-Maximum etwa 3 GiB.',
          '**48 GB und mehr:** Gemma 4 31B (19 GB) braucht bei 256K etwa 21 GiB. Mistral Small 3.2 24B (15 GB) braucht bei 128K 20 GiB mit f16-Cache und etwa 10 GiB mit q8_0.',
          '**1M Token:** Laut Konfiguration braucht Nemotron 3 Nano 30B bei 1M etwa 6 GiB KV-Cache zusätzlich zu seinem 18-GB-Download, der Speicher allein schließt es auf einem 32-GB-Rechner also nicht aus. NVIDIA liefert 256K als Standard und nennt H100- und A100-GPUs als unterstützte Hardware, und Unsloth warnt, dass 1M Abstürze durch Speichermangel auslösen kann, behandeln Sie es also als Experiment. Qwen gibt an, dass 1M Token bei Qwen3-30B-A3B-Instruct-2507 etwa 240 GB GPU-Speicher brauchen.',
