          '**La mémoire d\'un contexte long, ce sont les poids du modèle plus le cache KV, et le cache KV dépend de l\'architecture, pas seulement de la fenêtre.** Le cache KV stocke les clés et valeurs d\'attention de chaque token du contexte et s\'alloue en plus des poids.',
          'Octets KV par token = 2 (clés et valeurs) × couches d\'attention complète × têtes KV × dimension de tête × octets par valeur (2 pour le cache f16 par défaut). Llama 3.1 8B : 2 × 32 × 8 × 128 × 2 = 131 072 octets (128 Kio) par token, soit 16 Gio à 128K tokens, plus de trois fois son téléchargement de 4.9 Go.',
