          '**24 à 32 Go :** Gemma 4 26B-A4B (16 Go) exige environ 5.2 Gio à 256K. Qwen3.8 27B (18 Go) exige environ 8 Gio à 128K. gpt-oss 20B (14 Go) exige environ 3 Gio à son maximum de 128K.',
          '**48 Go et plus :** Gemma 4 31B (19 Go) exige environ 21 Gio à 256K. Mistral Small 3.2 24B (15 Go) exige 20 Gio à 128K avec un cache f16 et environ 10 Gio avec q8_0.',
          '**1M tokens :** d\'après sa configuration, Nemotron 3 Nano 30B exige environ 6 Gio de cache KV à 1M en plus de son téléchargement de 18 Go : la mémoire seule ne l\'exclut donc pas sur une machine de 32 Go. NVIDIA livre 256K par défaut et cite des GPU H100 et A100 comme matériel pris en charge, et Unsloth avertit que 1M peut provoquer des plantages par manque de mémoire : considérez-le comme une expérience. Qwen indique que 1M tokens sur Qwen3-30B-A3B-Instruct-2507 exige environ 240 Go de mémoire GPU.',
