            q: 'Puis-je résumer un livre entier avec un LLM local ?',
            a: 'Un livre de 300 pages représente à peu près 100K à 135K tokens : il tient dans une fenêtre de 256K (Qwen3.5, Qwen3.8, Gemma 4 à partir de 12B) et peut ne pas tenir dans une fenêtre de 128K une fois le résumé compté. Avec un modèle de 128K ou moins de mémoire, résumez chapitre par chapitre puis résumez les résumés. Définissez num_ctx explicitement pour que tout le livre soit dans le contexte actif.',
