          'RULER（Hsieh et al.、2024）は、いずれも32Kトークン以上をうたう17モデルを検証し、32Kで十分な性能を保ったのは約半数でした。NoLiMa（Modarressi et al.、2025）は128K以上をうたう13モデルを検証し、32Kでは11モデルが短いコンテキストでのスコアの50%を下回り、GPT-4oは99.3%から69.7%に低下しました。',
