    faqSchema: {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: [
        {
          '@type': 'Question',
          name: '2026年本地LLM能使用的最长上下文窗口是多少？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Llama 4 Scout列出10M token，但其模型卡在128K下报告基准测试，而且Ollama下载为67 GB。在能在一台普通机器上运行的模型中，NVIDIA Nemotron 3 Nano 30B-A3B支持1M token（默认配置为256K），Qwen3.8和Qwen3.5原生支持256K，通过YaRN最高可达约1M。长窗口是否可用，取决于内存，以及模型读取长输入的准确程度。',
          },
        },
        {
          '@type': 'Question',
          name: '128K的上下文窗口还够用吗？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '128K token约10万词，足够大多数单个文档。一本300页的书通常有7.5万到10万词，约100K到135K token，因此通常会超出128K窗口，或者几乎占满而没有余量留给问答。256K窗口可以容纳整本书和回答；再长就用RAG或分块。',
          },
        },
        {
          '@type': 'Question',
          name: '1M token的上下文需要多少内存？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '取决于架构。根据公开的配置，1M token时的f16 KV缓存在Qwen3.5 9B上约32 GiB，在Qwen3.8 27B上约64 GiB，在Nemotron 3 Nano 30B-A3B上约6 GiB，这还在权重之外。Qwen表示，Qwen3-30B-A3B-Instruct-2507处理1M token大约需要240 GB GPU内存。q8_0缓存可把KV数值减半，而读取1M token的提示词所需时间随长度增长，因此请把它留给偶尔的任务。',
          },
        },
        {
          '@type': 'Question',
          name: '为什么上下文窗口相同的模型所需内存差别很大？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'KV缓存随全注意力层数 × KV头数 × 头维度 × token数增长。Llama 3.1 8B每token需要128 KiB，Gemma 4 26B-A4B约20 KiB（30层中只有5层使用全注意力），Nemotron 3 Nano约6 KiB（52层中只有6层是注意力层）。滑动窗口层、线性注意力层和Mamba层保持固定大小的状态，而不是随窗口增长。',
          },
        },
        {
          '@type': 'Question',
          name: '什么是KV缓存，如何让它变小？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'KV缓存保存上下文中每个token的注意力键和值，使模型不必为每个新token重新计算。它在权重之外另行分配，并随上下文长度增长。要缩小它，可以降低num_ctx，启用Flash Attention并把OLLAMA_KV_CACHE_TYPE设为q8_0（约为f16内存的一半）或q4_0（约四分之一，长上下文下精度损失更大），或者选择每token缓存更小的模型。在Ollama中，缓存类型是全局的，对所有模型生效。',
          },
        },
        {
          '@type': 'Question',
          name: '为什么我的本地模型会忘记文档的开头？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '最可能是当前生效的上下文比你的文档小。无论模型支持多少，Ollama在VRAM低于24 GiB的GPU上默认4K token，24至48 GiB为32K，48 GiB及以上为256K，超出上下文的输入会被截断。请检查ollama ps的CONTEXT列，并通过OLLAMA_CONTEXT_LENGTH、/set parameter num_ctx、Modelfile或API的num_ctx选项提高它。',
          },
        },
        {
          '@type': 'Question',
          name: '如何在Ollama中设置128K上下文？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '创建包含FROM qwen3.5:9b和PARAMETER num_ctx 131072的Modelfile，运行ollama create qwen3.5-9b-128k -f Modelfile，然后ollama run qwen3.5-9b-128k，并用ollama ps验证。也可以用OLLAMA_CONTEXT_LENGTH=131072 ollama serve启动服务器。请先确认权重加KV缓存能放进内存；对Qwen3.5 9B来说，约为6.6 GB加4 GiB。',
          },
        },
        {
          '@type': 'Question',
          name: '上下文越长，本地LLM会越慢吗？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '会。模型必须先读完整个提示词（预填充）才能写出第一个token，因此首个token的等待时间随提示词长度增长，而且对更大缓存做注意力计算也会降低生成速度。线性注意力层和Mamba层会减缓这种增长，但不会消除。请在你的硬件上用ollama run <model> --verbose测量，它会输出提示词评估和生成的速率。',
          },
        },
        {
          '@type': 'Question',
          name: '什么是“中间丢失”问题，它现在还适用吗？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: 'Liu等人（2023）发现，当相关文本位于输入的开头或结尾时，语言模型回答最准确，位于中间时准确率较低。RULER（2024）和NoLiMa（2025）随后表明，许多标称32K到128K窗口的模型在远未达到上限时就已经丢失准确率。这些研究测试的是较早的模型，因此请自己验证：把一个事实藏在长提示词的10%、50%和90%位置并提问。把关键指令放在开头或结尾，或只检索相关段落。',
          },
        },
        {
          '@type': 'Question',
          name: '回答文档问题时，长上下文和RAG哪个更好？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '当答案只在大型集合的少数段落中时，RAG通常更省内存、更省时间，因为它把提示词控制在几千token。当模型必须对单个完整文档做推理时，长上下文更好，例如合同、代码库或书籍章节，分块会切断其中的交叉引用。许多方案两者结合，把检索到的整段章节放入32K到128K的窗口。',
          },
        },
        {
          '@type': 'Question',
          name: '我能用本地LLM总结一整本书吗？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '一本300页的书约100K到135K token，因此可以放进256K窗口（Qwen3.5、Qwen3.8、Gemma 4的12B及以上），但把摘要计算在内后，可能放不进128K窗口。如果用128K模型或内存较少，请逐章总结，再总结这些摘要。请明确设置num_ctx，让整本书都在当前上下文中。',
          },
        },
        {
          '@type': 'Question',
          name: '非英文文档会占用更多上下文窗口吗？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '可能会。Petrov等人（2023）发现，取决于分词器，同样的文本在一种语言中所需的token最多可达另一种语言的15倍。请用你的模型来计算token，而不是使用英文“每token约0.75个单词”的规则：ollama run <model> --verbose会输出提示词的token数。',
          },
        },
        {
          '@type': 'Question',
          name: '哪些长上下文模型能在16 GB的机器上运行？',
          acceptedAnswer: {
            '@type': 'Answer',
            text: '按内存计算，Qwen3.5 9B（下载6.6 GB，128K时再加约4 GiB KV缓存）和Gemma 4 12B（7.7 GB，完整256K窗口时再加约4.3 GiB）都能放进16 GB并留出几GB余量。这些是根据公开配置算出的，并非实测；请用ollama ps确认。',
          },
        },
      ],
      inLanguage: 'zh',
    },
