          '每token的KV字节数 = 2（键和值）× 全注意力层数 × KV头数 × 头维度 × 每个值的字节数（默认f16缓存为2）。Llama 3.1 8B：2 × 32 × 8 × 128 × 2 = 131,072字节（128 KiB）/token，128K token时为16 GiB，是其4.9 GB下载大小的三倍多。',
