          'RULER（Hsieh等人，2024）测试了17个都标称32K token或更多的模型，只有约一半在32K时保持了令人满意的表现。NoLiMa（Modarressi等人，2025）测试了13个标称至少128K的模型，在32K时其中11个低于其短上下文得分的50%，GPT-4o从99.3%降到69.7%。',
          '这些研究早于本指南中的大多数模型，请把它们当作这一规律的证据，而不是这里所列任何模型的得分。要自己验证某个模型，请把一个事实藏在长提示词的10%、50%和90%位置，换一种说法提问，并在32K、64K和128K下重复。',
