    intro: '2026년에 128K 토큰은 로컬 LLM의 상한이 아니라 입문 수준입니다. Ollama 라이브러리는 Qwen3.5, Qwen3.8, Gemma 4(12B 이상)를 256K, NVIDIA Nemotron 3 Nano 30B를 1M, Llama 4 Scout를 10M으로 표기합니다. 실제 한계는 메모리입니다. 128K에서 KV 캐시는 아키텍처에 따라 1 GiB 미만(Nemotron 3 Nano)에서 20 GiB(Mistral Small 3.2)까지 차이가 나며, Ollama는 VRAM 24 GiB 미만 GPU에서 기본값이 4K 토큰에 불과합니다. 이 가이드는 어떤 모델이 어떤 윈도우를 지원하는지, 메모리가 얼마나 필요한지, 컨텍스트 길이를 어떻게 설정하는지 설명합니다.',
