          '**긴 컨텍스트에 필요한 메모리는 모델 가중치와 KV 캐시의 합이며, KV 캐시는 윈도우뿐 아니라 아키텍처에도 좌우됩니다.** KV 캐시는 컨텍스트 안의 모든 토큰에 대한 어텐션의 키와 값을 저장하며 가중치와 별도로 할당됩니다.',
