          'RULER(Hsieh 등, 2024)는 모두 32K 토큰 이상을 표기한 17개 모델을 시험했으며, 32K에서 만족스러운 성능을 유지한 모델은 약 절반이었습니다. NoLiMa(Modarressi 등, 2025)는 128K 이상을 표기한 13개 모델을 시험했고, 32K에서 11개가 짧은 컨텍스트 점수의 50% 아래로 떨어졌으며 GPT-4o는 99.3%에서 69.7%로 하락했습니다.',
