        content: [
          '**Ollama는 VRAM에 따라 기본 컨텍스트를 정합니다. 24 GiB 미만에서는 4K 토큰, 24~48 GiB에서는 32K, 48 GiB 이상에서는 256K입니다.** 현재 컨텍스트를 넘는 입력은 잘리므로 모델은 긴 문서의 시작 부분을 보지 못합니다.',
          '컨텍스트는 Ollama 앱의 슬라이더, 환경 변수 OLLAMA_CONTEXT_LENGTH, ollama run 안의 /set parameter num_ctx, Modelfile, API의 num_ctx 옵션으로 설정할 수 있습니다. 결과는 ollama ps로 확인하십시오.',
          'LM Studio에서는 My Models를 열고 모델의 톱니바퀴 아이콘을 눌러 컨텍스트 크기와 Flash Attention을 설정합니다. llama.cpp에서는 -c가 컨텍스트 크기(0이면 모델에서 불러옴), -fa가 Flash Attention, --cache-type-k와 --cache-type-v가 KV 캐시 양자화를 제어합니다.',
          'Ollama는 Flash Attention이 켜져 있을 때만 KV 캐시를 양자화하며, 이 설정은 모든 모델에 전역으로 적용됩니다. OLLAMA_KV_CACHE_TYPE=q8_0은 f16의 약 절반, q4_0은 약 4분의 1 메모리를 사용합니다.',
        ],
        codeBlock: '# 1. Check what a loaded model really uses (see the CONTEXT column)\nollama ps\n\n# 2. Server-wide default (the Ollama app has a context slider instead)\nOLLAMA_CONTEXT_LENGTH=65536 ollama serve\n\n# 3. One interactive session\nollama run qwen3.5:9b\n>>> /set parameter num_ctx 65536\n\n# 4. A persistent custom model\ncat << EOF > Modelfile\nFROM qwen3.5:9b\nPARAMETER num_ctx 131072\nEOF\nollama create qwen3.5-9b-128k -f Modelfile\nollama run qwen3.5-9b-128k\n\n# 5. Optional: shrink the KV cache (global setting, needs Flash Attention)\nOLLAMA_FLASH_ATTENTION=1 OLLAMA_KV_CACHE_TYPE=q8_0 ollama serve\n\n# llama.cpp equivalent\nllama-server -m model.gguf -c 131072 -fa on --cache-type-k q8_0 --cache-type-v q8_0',
