          'RAG(검색 증강 생성)는 가장 관련 있는 조각을 가져오며, 합계가 수천 토큰인 경우가 많아 프롬프트를 짧게 유지합니다. 긴 컨텍스트는 계약서의 조항이나 코드베이스의 호출 관계처럼 청크 분할로 끊길 수 있는 상호 참조를 유지합니다.',
