          '**기본 컨텍스트를 믿는 것:** Ollama는 모델이 지원하는 길이와 관계없이 VRAM 24 GiB 미만에서 기본값이 4K 토큰이므로, 100쪽 문서는 모델이 읽기 전에 잘립니다. 컨텍스트를 명시적으로 설정하고 ollama ps의 CONTEXT 열에서 확인하십시오.',
